"""Sprout tutor agent (hosted build). Generated by build_hosted.py; edit the source files, not this.

Needs ASI_ONE_API_KEY and SPACETIMEDB_TOKEN (plus SPACETIMEDB_DB) in the editor's .env.
No `from __future__ import annotations`: uAgents reads handler type hints as classes."""

# ---- sprout_db.py ----

import os
from datetime import date, datetime, time, timezone

import requests

HOST = os.getenv("SPACETIMEDB_HOST", "https://maincloud.spacetimedb.com").rstrip("/")
DB = os.getenv("SPACETIMEDB_DB", "sprout-live")
TIMEOUT = 20


class DbError(RuntimeError):
    """A reducer rejected the call or the database couldn't be reached."""


def enabled() -> bool:
    return bool(os.getenv("SPACETIMEDB_TOKEN"))


def _headers() -> dict:
    return {"Authorization": f"Bearer {os.environ['SPACETIMEDB_TOKEN']}"}


# ---- argument encoding (SpacetimeDB's JSON format) ----

def some(value):
    return {"some": value}


NONE = {"none": []}


def opt(value):
    """Option argument: {"some": v} or {"none": []}."""
    return NONE if value is None or value == "" else some(value)


def timestamp(value):
    """A date, datetime or YYYY-MM-DD string as a SpacetimeDB timestamp (UTC midnight for dates)."""
    if isinstance(value, str):
        value = date.fromisoformat(value)
    if isinstance(value, date) and not isinstance(value, datetime):
        value = datetime.combine(value, time(0), tzinfo=timezone.utc)
    micros = int(value.timestamp() * 1_000_000)
    return {"__timestamp_micros_since_unix_epoch__": micros}


# ---- calls ----

def call(reducer: str, *args):
    try:
        r = requests.post(f"{HOST}/v1/database/{DB}/call/{reducer}", json=list(args),
                          headers=_headers(), timeout=TIMEOUT)
    except requests.RequestException as err:
        raise DbError(f"{reducer}: {err}") from err
    if not r.ok:
        raise DbError(f"{reducer}: {r.text.strip()[:300]}")


def _decode(value):
    """SQL results return options as [0, value] (some) or [1, []] (none)."""
    if isinstance(value, list) and len(value) == 2 and value[0] in (0, 1) and (value[0] == 0 or value[1] == []):
        return value[1] if value[0] == 0 else None
    return value


def sql(query: str) -> list:
    try:
        r = requests.post(f"{HOST}/v1/database/{DB}/sql", data=query, headers=_headers(), timeout=TIMEOUT)
    except requests.RequestException as err:
        raise DbError(f"sql: {err}") from err
    if not r.ok:
        raise DbError(f"sql: {r.text.strip()[:300]}")
    result = r.json()[0]
    names = [e["name"]["some"] for e in result["schema"]["elements"]]
    return [dict(zip(names, (_decode(v) for v in row))) for row in result["rows"]]


def sql_str(text: str) -> str:
    """A SQL string literal."""
    return "'" + str(text).replace("'", "''") + "'"


# ---- relay.py ----

import os
from datetime import datetime, timezone
from uuid import uuid4

from uagents import Context, Model, Protocol
from uagents_core.contrib.protocols.chat import ChatMessage, StartSessionContent, TextContent


class StudentTurn(Model):
    user: str             # the student's ASI:One address
    text: str = ""        # what they typed, or a card's selection JSON
    start: bool = False   # a brand-new chat


class StudentReplies(Model):
    user: str
    messages: list[str]   # ChatMessage JSON, in the order they were sent


def turn_message(turn: StudentTurn) -> ChatMessage:
    content = [StartSessionContent(type="start-session")] if turn.start else []
    if turn.text:
        content.append(TextContent(type="text", text=turn.text))
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(), content=content)


def fresh(raw: str) -> ChatMessage:
    """A relayed message with its own id and time, as the orchestrator's message to the student."""
    msg = ChatMessage.model_validate_json(raw)
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(), content=msg.content)


def trusted() -> set:
    return {a.strip() for a in os.getenv("TRUSTED_ORCHESTRATORS", "").split(",") if a.strip()}


class CaptureContext:
    """Stands in for the handler's Context: messages to the student are collected instead of sent.

    Storage, logging and messages to anyone else go through the real context.
    """

    def __init__(self, ctx: Context, user: str):
        self._ctx, self._user, self.messages = ctx, user, []

    def __getattr__(self, name):
        return getattr(self._ctx, name)

    async def send(self, destination: str, message, *args, **kwargs):
        if destination == self._user:
            if isinstance(message, ChatMessage):
                self.messages.append(message.model_dump_json())
            return None  # acknowledgements to the student are the orchestrator's job
        return await self._ctx.send(destination, message, *args, **kwargs)


async def handle_turn(ctx: Context, sender: str, turn: StudentTurn, on_chat):
    """Runs the specialist's chat handler as the student and replies with what it would have sent."""
    if sender not in trusted():
        ctx.logger.warning(f"ignored a relayed turn from untrusted {sender[:20]}")
        return
    capture = CaptureContext(ctx, turn.user)
    await on_chat(capture, turn.user, turn_message(turn))
    await ctx.send(sender, StudentReplies(user=turn.user, messages=capture.messages))


def relay_protocol(on_chat) -> Protocol:
    """Specialist side: runs `on_chat(ctx, user, ChatMessage)` for each trusted StudentTurn."""
    proto = Protocol(name="SproutRelay", version="0.1.0")

    @proto.on_message(model=StudentTurn, replies=StudentReplies)
    async def on_turn(ctx: Context, sender: str, turn: StudentTurn):
        await handle_turn(ctx, sender, turn, on_chat)

    return proto


# ---- learning.py ----

import time
from datetime import date, datetime, timezone


FORMATS = ["worked_example", "flashcards", "diagram", "analogy"]
PREREQ_SOLID = 0.7   # same cut-offs as spacetimedb/src/algorithms.ts
MASTERED = 0.95


def micros(ts) -> int:
    """SQL returns timestamps as [micros] (or None)."""
    if ts is None:
        return 0
    return ts[0] if isinstance(ts, list) else int(ts)


def days_until(ts, now=None):
    """Calendar days from today to the exam date (stored as UTC midnight)."""
    if ts is None:
        return None
    exam = datetime.fromtimestamp(micros(ts) / 1_000_000, timezone.utc).date()
    today = datetime.fromtimestamp(now, timezone.utc).date() if now else date.today()
    return max(0, (exam - today).days)


def active_courses(address: str) -> list:
    rows = sql(f"SELECT id, name, exam_date, created_at FROM course "
               f"WHERE user_address = {sql_str(address)} AND status = 'active'")
    return sorted(rows, key=lambda r: micros(r["created_at"]), reverse=True)


def course(course_id: int) -> dict:
    return sql(f"SELECT id, name, exam_date FROM course WHERE id = {int(course_id)}")[0]


def snapshot(address: str, course_id: int, now=None) -> dict:
    """Concepts with mastery, what's due, and the last session's recap."""
    now_us = int((now or time.time()) * 1_000_000)
    concepts = sql(f"SELECT id, name, summary FROM concept WHERE course_id = {int(course_id)}")
    rows = {r["concept_id"]: r for r in sql(
        f"SELECT concept_id, p_mastered, attempts, next_review FROM mastery "
        f"WHERE user_address = {sql_str(address)} AND course_id = {int(course_id)}")}
    items = []
    for c in concepts:
        m = rows.get(c["id"], {})
        items.append({
            "id": c["id"], "name": c["name"], "summary": c["summary"],
            "p": m.get("p_mastered"), "attempts": m.get("attempts", 0),  # None until the student is tested
            "due": bool(m.get("next_review")) and micros(m.get("next_review")) <= now_us,
        })
    ended = [s for s in sql(f"SELECT started_at, ended_at, summary FROM session WHERE user_address = {sql_str(address)}")
             if s.get("ended_at") and s.get("summary")]
    recap = max(ended, key=lambda s: micros(s["started_at"]))["summary"] if ended else ""
    return {"concepts": items, "due": sum(i["due"] for i in items),
            "untested": sum(i["attempts"] == 0 for i in items), "recap": recap}


def start_session(address: str, course_id: int) -> int:
    call("upsert_learner", address, NONE)
    call("start_session", address, some(int(course_id)))
    open_sessions = [s for s in sql(f"SELECT id, started_at, ended_at FROM session WHERE user_address = {sql_str(address)}")
                     if not s.get("ended_at")]
    return max(open_sessions, key=lambda s: micros(s["started_at"]))["id"]


def end_session(address: str, session_id: int, summary: str, last_concept_id=None):
    call("end_session", address, int(session_id), summary, opt(last_concept_id))


def next_step(address: str, course_id: int, mode: str) -> dict:
    """Asks the database for the next concept. mode: teach | review | diagnostic."""
    call("compute_next_step", address, int(course_id), mode)
    row = sql(f"SELECT concept_id, format, mode, reason FROM next_step "
              f"WHERE key = {sql_str(f'{address}:{int(course_id)}')}")[0]
    return {"concept_id": row["concept_id"], "format": row["format"], "mode": row["mode"], "reason": row["reason"]}


def concept(concept_id: int) -> dict:
    return sql(f"SELECT id, name, summary FROM concept WHERE id = {int(concept_id)}")[0]


def record(address: str, concept_id: int, correct: bool, kind: str, fmt, session_id, question: str) -> tuple:
    """Saves one answer and returns (mastery before, mastery after)."""
    key = sql_str(f"{address}:{int(concept_id)}")
    row = sql(f"SELECT p_mastered FROM mastery WHERE key = {key}")
    # A first answer starts from the concept's prior, which the database seeds the mastery row with.
    before = row[0]["p_mastered"] if row else sql(f"SELECT p_init FROM concept WHERE id = {int(concept_id)}")[0]["p_init"]
    call("record_attempt", address, int(concept_id), bool(correct), kind,
         opt(fmt if fmt in FORMATS else None), opt(session_id), opt(question[:500]))
    after = sql(f"SELECT p_mastered FROM mastery WHERE key = {key}")[0]["p_mastered"]
    return before, after


def format_stats(address: str) -> list:
    return sql(f"SELECT format, alpha, beta, uses FROM format_weight WHERE user_address = {sql_str(address)}")


def format_insight(stats: list, min_uses: int = 3):
    """One plain line comparing the best and worst formats once there's evidence, else None."""
    used = [s for s in stats if s["uses"] >= min_uses]
    if len(used) < 2:
        return None
    rate = lambda s: s["alpha"] / (s["alpha"] + s["beta"])
    best, worst = max(used, key=rate), min(used, key=rate)
    if rate(best) - rate(worst) < 0.1:
        return None
    label = {"worked_example": "worked examples", "flashcards": "flashcards",
             "diagram": "diagrams", "analogy": "analogies"}.get
    return (f"{label(best['format'], best['format']).capitalize()} have worked better for you than {label(worst['format'], worst['format'])}: "
            f"{rate(best):.0%} vs {rate(worst):.0%} of check questions right, so I'll lean on them.")


# ---- content.py ----

import json
import os
import random
import re

import requests

ASI_URL = "https://api.asi1.ai/v1/chat/completions"
MODEL = os.getenv("ASI_ONE_MODEL", "asi1-mini")

TUTOR = ("You are Sprout, a patient tutor for a college student. Be accurate and concise, use the "
         "course's own terms, and never pad answers with filler or praise.")

LESSON_STYLES = {
    "worked_example": "Teach it with one fully worked example, step by step, then a one-line takeaway.",
    "flashcards": "Teach it as 6 flashcards, each as 'Front: ...' then 'Back: ...', building from basics to the key idea.",
    "diagram": "Teach it with a small text diagram in a code block (ASCII boxes and arrows), then 3 short bullet notes that walk through it.",
    "analogy": "Teach it with one everyday analogy, then map each part of the analogy back to the real idea, then note where the analogy breaks down.",
}


def call_llm(prompt: str, temperature: float = 0.4) -> str:
    resp = requests.post(
        ASI_URL,
        headers={"Authorization": f"Bearer {os.environ['ASI_ONE_API_KEY']}"},
        json={"model": MODEL, "temperature": temperature,
              "messages": [{"role": "system", "content": TUTOR}, {"role": "user", "content": prompt}]},
        timeout=90,
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"].strip()


def _json_object(text: str) -> dict:
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.DOTALL)
    return json.loads(fenced.group(1) if fenced else text[text.find("{"): text.rfind("}") + 1])


def clean_question(raw: dict, rng=random) -> dict:
    """Validates a model-written question and shuffles the choices so the answer isn't always A."""
    question = str(raw.get("question", "")).strip()
    # Drop "A) " style labels the model sometimes adds; the card shows its own buttons.
    choices = [re.sub(r"^[A-Ea-e][).:]\s+", "", str(c).strip()) for c in raw.get("choices", []) if str(c).strip()]
    idx = int(raw.get("correct_index", -1))
    if not question or not 3 <= len(choices) <= 5 or not 0 <= idx < len(choices) or len(set(choices)) != len(choices):
        raise ValueError("malformed question")
    correct = choices[idx]
    rng.shuffle(choices)
    return {"question": question, "choices": choices, "correct_index": choices.index(correct),
            "explanation": str(raw.get("explanation", "")).strip()}


def make_question(course: str, concept: dict, kind: str, avoid: list = ()) -> dict:
    """One multiple-choice question. diagnostic: gauge prior knowledge; check/review: test what was taught."""
    purpose = {"diagnostic": "find out whether the student already understands it",
               "check": "check that the student understood the lesson they just read",
               "review": "check the student still remembers it a few days later"}[kind]
    seen = f"\nDon't repeat these questions: {json.dumps(list(avoid)[-4:])}" if avoid else ""
    prompt = (f"Course: {course}\nConcept: {concept['name']}: {concept['summary']}\n\n"
              f"Write one multiple-choice question to {purpose}. Test understanding, not memorized wording, at "
              f"the level of a course exam. Give 4 choices with plausible wrong answers.{seen}\n\n"
              'Return only JSON: {"question": str, "choices": [str, str, str, str], "correct_index": int, '
              '"explanation": "one or two sentences on why the answer is right"}')
    last = None
    for _ in range(2):
        try:
            return clean_question(_json_object(call_llm(prompt)))
        except (ValueError, KeyError, TypeError, json.JSONDecodeError) as err:
            last = err
    raise ValueError(f"couldn't write a question: {last}")


def make_lesson(course: str, concept: dict, fmt: str) -> str:
    style = LESSON_STYLES.get(fmt, LESSON_STYLES["worked_example"])
    return call_llm(f"Course: {course}\nConcept: {concept['name']}: {concept['summary']}\n\n"
                    f"Teach this concept to a student who finds it shaky. {style} "
                    f"Keep it under 220 words, in Markdown, with no heading.")


# ---- cards.py ----

import json
import os
from datetime import datetime, timezone
from urllib.parse import quote, urlencode
from uuid import uuid4

from uagents_core.contrib.protocols.chat import ChatMessage, EndSessionContent, MetadataContent, TextContent

CARDS_URL = os.getenv("SPROUT_CARDS_URL", "https://sprout-cards-six.vercel.app")
CARD_WIDTH = "560"
MAX_ROWS = 8
FORMAT_LABELS = {"worked_example": "Worked example", "flashcards": "Flashcards",
                 "diagram": "Diagram", "analogy": "Analogy"}
KIND_LABELS = {"diagnostic": "Diagnostic", "check": "Check", "review": "Review"}


def text_message(text: str) -> ChatMessage:
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(),
                       content=[TextContent(type="text", text=text), EndSessionContent(type="end-session")])


def _card(text: str, root: dict) -> ChatMessage:
    return ChatMessage(timestamp=datetime.now(timezone.utc), msg_id=uuid4(), content=[
        TextContent(type="text", text=text),
        MetadataContent(type="metadata", metadata={
            "card_protocol_version": "1",
            "requires_card_interaction": "true",
            "card_kind": "custom",
            "card_payload": json.dumps({"root": root}),
            "preferred_drawer_width_px": CARD_WIDTH,
        }),
    ])


def parse_selection(text: str) -> dict:
    """Card replies are JSON text, sometimes after an @mention. Returns {} for plain chat."""
    text = (text or "").strip()
    if text.startswith("@"):
        text = text.split(None, 1)[1] if " " in text else ""
    try:
        data = json.loads(text)
    except (TypeError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    selection = data.get("selection", data)
    return selection if isinstance(selection, dict) and selection.get("action") else {}


def _button(label: str, action: str, primary: bool = False, **extra) -> dict:
    return {"type": "button", "label": label, "primary": primary, "action": {"selection": {"action": action, **extra}}}


def _row(*buttons) -> dict:
    return {"type": "group", "direction": "row", "gap": 8, "children": [b for b in buttons if b]}


def _section(*children) -> dict:
    return {"type": "section", "children": [c for c in children if c]}


def tested(c: dict) -> bool:
    return c["p"] is not None and c["attempts"] > 0


def snapshot_rows(concepts: list) -> list:
    """Tested concepts first, weakest first, so the card shows what needs work; then untested ones."""
    return sorted(concepts, key=lambda c: (not tested(c), c["p"] if tested(c) else 0, c["name"]))[:MAX_ROWS]


def snapshot_row(c: dict) -> str:
    """label~bar~tail. Untested concepts get an empty bar and a dash, not BKT's prior."""
    if not tested(c):
        return f"{c['name']}~0~–"
    return f"{c['name']}~{c['p']:.2f}~{round(c['p'] * 100)}%"


def snapshot_image(course_name: str, snap: dict, exam_days) -> tuple:
    rows = snapshot_rows(snap["concepts"])
    bits = []
    if exam_days is not None:
        bits.append("exam today" if exam_days == 0 else f"exam in {exam_days} day{'s' if exam_days != 1 else ''}")
    n = len(snap["concepts"])
    done = sum(tested(c) for c in snap["concepts"])
    bits.append(f"{done} of {n} concepts tested" if done else f"{n} concepts, none tested yet")
    if snap["due"]:
        bits.append(f"{snap['due']} due for review")
    params = [("title", course_name), ("subtitle", " · ".join(bits))]
    params += [("r", snapshot_row(c)) for c in rows]
    height = 40 + 80 + 44 + 34 + len(rows) * 58 + 30  # cardSize() in cards/lib/render.js
    return f"{CARDS_URL}/api/card?{urlencode(params, quote_via=quote)}", f"1080:{height}"


def home_card(course_name: str, snap: dict, exam_days, insight=None, opener: str = "") -> ChatMessage:
    src, ratio = snapshot_image(course_name, snap, exam_days)
    root = _section(
        {"type": "image", "src": src, "alt": f"{course_name} progress", "aspect_ratio": ratio},
        {"type": "text", "style": "muted", "value": f"Last time: {snap['recap']}"} if snap["recap"] else None,
        {"type": "text", "style": "muted", "value": insight} if insight else None,
        _row(_button("Learn next", "teach", True),
             _button("Diagnostic quiz", "diagnostic", True) if snap["untested"] else None),
        _row(_button(f"Review ({snap['due']} due)", "review") if snap["due"] else None,
             _button("Done for today", "done")),
    )
    return _card(opener or f"Here's where you are in {course_name}.", root)


def course_picker_card(courses: list) -> ChatMessage:
    root = _section(
        {"type": "heading", "value": "Which course?", "level": 2},
        {"type": "input", "name": "course_id", "kind": "select", "label": "Course", "required": True,
         "options": [{"value": str(c["id"]), "label": c["name"]} for c in courses]},
        _row(_button("Open", "open", True)),
    )
    return _card("Pick a course to study.", root)


def question_card(concept_name: str, kind: str, q: dict, number: int, total: int) -> ChatMessage:
    label = KIND_LABELS.get(kind, "Question") + (f" {number} of {total}" if total > 1 else "")
    root = _section(
        {"type": "heading", "value": concept_name, "level": 2},
        {"type": "badge", "label": label, "variant": "info"},
        {"type": "text", "style": "body", "value": q["question"]},
        {"type": "group", "direction": "column", "gap": 8,
         "children": [_button(choice, "answer", False, choice=i) for i, choice in enumerate(q["choices"])]},
    )
    return _card(q["question"], root)


def lesson_card(concept_name: str, fmt: str, lesson: str) -> ChatMessage:
    root = _section(
        {"type": "heading", "value": concept_name, "level": 2},
        {"type": "badge", "label": FORMAT_LABELS.get(fmt, "Lesson"), "variant": "info"},
        _row(_button("Check my understanding", "check", True), _button("Back to overview", "home")),
    )
    return _card(lesson, root)


def feedback_card(q: dict, choice: int, before: float, after: float, concept_name: str,
                  next_label: str, next_action: str) -> ChatMessage:
    correct = choice == q["correct_index"]
    root = _section(
        {"type": "heading", "value": "Correct" if correct else "Not quite", "level": 2},
        {"type": "badge", "label": f"{concept_name}: {before:.0%} → {after:.0%}", "variant": "success" if after >= before else "warning"},
        {"type": "text", "style": "body", "value": f"Answer: {q['choices'][q['correct_index']]}"},
        {"type": "text", "style": "muted", "value": q["explanation"]} if q.get("explanation") else None,
        _row(_button(next_label, next_action, True), _button("Back to overview", "home")),
    )
    return _card("Correct!" if correct else f"Not quite. The answer is {q['choices'][q['correct_index']]}.", root)


# ---- agent.py ----

import asyncio
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

from uagents import Agent, Context, Protocol
from uagents_core.contrib.protocols.chat import (
    ChatAcknowledgement,
    ChatMessage,
    StartSessionContent,
    TextContent,
    chat_protocol_spec,
)


CURRICULUM_HANDLE = os.getenv("CURRICULUM_HANDLE", "@blank-agent-181")
QUESTIONS = {"diagnostic": 5, "review": 3, "check": 2}

agent = Agent()

chat = Protocol(spec=chat_protocol_spec)


def run(fn, *args):
    return asyncio.to_thread(fn, *args)


def load(ctx: Context, sender: str) -> dict:
    return ctx.storage.get(f"tutor:{sender}") or {}


def save(ctx: Context, sender: str, state: dict):
    ctx.storage.set(f"tutor:{sender}", state)


@chat.on_message(ChatMessage)
async def on_chat(ctx: Context, sender: str, msg: ChatMessage):
    await ctx.send(sender, ChatAcknowledgement(timestamp=datetime.now(timezone.utc), acknowledged_msg_id=msg.msg_id))
    if not enabled():
        await ctx.send(sender, text_message("The tutor isn't connected to Sprout's database yet (SPACETIMEDB_TOKEN)."))
        return
    text = "".join(c.text for c in msg.content if isinstance(c, TextContent)).strip()
    sel = {} if any(isinstance(c, StartSessionContent) for c in msg.content) else parse_selection(text)
    try:
        await handle(ctx, sender, sel.get("action") or "start", sel)
    except DbError as err:
        ctx.logger.error(f"database: {err}")
        await ctx.send(sender, text_message("I couldn't reach Sprout's database just now. Try again in a moment."))
    except Exception as err:  # the model or a network call failed; say so plainly
        ctx.logger.error(f"tutor error: {err}")
        await ctx.send(sender, text_message("Something went wrong writing that. Say \"hi\" to pick up where you were."))


@chat.on_message(ChatAcknowledgement)
async def on_ack(ctx: Context, sender: str, msg: ChatAcknowledgement):
    pass


async def handle(ctx: Context, sender: str, action: str, sel: dict):
    state = load(ctx, sender)
    if action == "open" and sel.get("course_id"):
        await open_course(ctx, sender, int(sel["course_id"]))
    elif action == "start" or not state.get("course_id"):
        await start(ctx, sender, state)
    elif action == "home":
        await show_home(ctx, sender, state)
    elif action in ("diagnostic", "review"):
        state.update(mode=action, number=0, total=QUESTIONS[action])
        await ask(ctx, sender, state)
    elif action == "teach":
        await teach(ctx, sender, state)
    elif action == "check":
        state.update(mode="check", number=0, total=QUESTIONS["check"])
        await ask(ctx, sender, state)
    elif action == "next":
        await ask(ctx, sender, state)
    elif action == "answer":
        await answer(ctx, sender, state, sel.get("choice"))
    elif action == "done":
        await finish(ctx, sender, state)
    else:
        await show_home(ctx, sender, state)


async def start(ctx: Context, sender: str, state: dict):
    courses = await run(active_courses, sender)
    if not courses:
        await ctx.send(sender, text_message(
            f"You don't have a course yet. Paste your syllabus to Sprout Curriculum ({CURRICULUM_HANDLE}), "
            "tap \"Looks right\", then come back here."))
    elif len(courses) == 1:
        await open_course(ctx, sender, courses[0]["id"])
    else:
        await ctx.send(sender, course_picker_card(courses))


async def open_course(ctx: Context, sender: str, course_id: int):
    state = load(ctx, sender)
    if state.get("course_id") != course_id or not state.get("session_id"):
        state = {"course_id": course_id, "session_id": await run(start_session, sender, course_id),
                 "studied": [], "answered": 0, "right": 0, "asked": []}
        save(ctx, sender, state)
    await show_home(ctx, sender, state, welcome=True)


async def show_home(ctx: Context, sender: str, state: dict, welcome: bool = False):
    c = await run(course, state["course_id"])
    snap = await run(snapshot, sender, state["course_id"])
    days = days_until(c.get("exam_date"))
    insight = format_insight(await run(format_stats, sender))
    opener = ""
    if welcome and snap["recap"]:
        opener = f"Welcome back to {c['name']}." + (f" Your exam is in {days} days." if days else "")
    state["course_name"] = c["name"]
    save(ctx, sender, state)
    await ctx.send(sender, home_card(c["name"], snap, days, insight, opener))


async def teach(ctx: Context, sender: str, state: dict):
    step = await run(next_step, sender, state["course_id"], "teach")
    if step["mode"] == "complete":
        await ctx.send(sender, text_message("You've mastered every concept in this course. Try a review instead."))
        return
    con = await run(concept, step["concept_id"])
    lesson = await run(make_lesson, state["course_name"], con, step["format"])
    state.update(concept_id=con["id"], concept_name=con["name"], fmt=step["format"])
    save(ctx, sender, state)
    await ctx.send(sender, lesson_card(con["name"], step["format"], lesson))


async def ask(ctx: Context, sender: str, state: dict):
    mode = state.get("mode", "diagnostic")
    if mode == "check":
        con = await run(concept, state["concept_id"])
    else:
        step = await run(next_step, sender, state["course_id"], mode)
        if step["mode"] == "complete":
            done = "Nothing is due for review right now." if mode == "review" else "You've been quizzed on every concept."
            await ctx.send(sender, text_message(f"{done} Say \"hi\" to see your progress."))
            return
        con = await run(concept, step["concept_id"])
    q = await run(make_question, state["course_name"], con, mode, state.get("asked", []))
    state.update(concept_id=con["id"], concept_name=con["name"], question=q,
                 number=state.get("number", 0) + 1, asked=(state.get("asked", []) + [q["question"]])[-10:])
    save(ctx, sender, state)
    await ctx.send(sender, question_card(con["name"], mode, q, state["number"], state["total"]))


async def answer(ctx: Context, sender: str, state: dict, choice):
    q = state.get("question")
    try:
        choice = int(choice)
    except (TypeError, ValueError):
        choice = -1
    if not q or not 0 <= choice < len(q["choices"]):
        await show_home(ctx, sender, state)
        return
    mode = state.get("mode", "diagnostic")
    correct = choice == q["correct_index"]
    fmt = state.get("fmt") if mode == "check" else None  # only taught material says anything about a format
    before, after = await run(record, sender, state["concept_id"], correct, mode, fmt, state["session_id"], q["question"])
    state.update(question=None, answered=state.get("answered", 0) + 1, right=state.get("right", 0) + int(correct),
                 studied=list(dict.fromkeys(state.get("studied", []) + [state["concept_name"]])),
                 last_concept_id=state["concept_id"])
    save(ctx, sender, state)
    if state["number"] < state["total"]:
        nxt = ("Next question", "next")
    elif mode == "check":
        nxt = ("Learn the next concept", "teach")
    else:
        nxt = ("See my progress", "home")
    await ctx.send(sender, feedback_card(q, choice, before, after, state["concept_name"], *nxt))


async def finish(ctx: Context, sender: str, state: dict):
    studied, answered, right = state.get("studied", []), state.get("answered", 0), state.get("right", 0)
    summary = (f"Studied {', '.join(studied[:4])}; got {right} of {answered} questions right."
               if answered else "Opened the course but didn't answer any questions.")
    await run(end_session, sender, state["session_id"], summary, state.get("last_concept_id"))
    save(ctx, sender, {"course_id": state["course_id"]})  # the next chat starts a fresh session
    await ctx.send(sender, text_message(f"Nice work. {summary} Next time we'll pick up right here."))


agent.include(chat, publish_manifest=True)
agent.include(relay_protocol(on_chat))  # turns relayed by the orchestrator
